  function normalizeUrl(u){
    u = u.trim();
    if(!u) return '';
    if(!/^https?:\/\//i.test(u)) u = 'https://' + u;
    return u;
  }
  // Sites without a brand icon get their own favicon (site/favicon.ico, then Google's
  // favicon service), and if neither loads, a colored letter tile — so every link has an icon.
  function faviconHost(url){
    try{ return new URL(url).hostname.replace(/^www\./,''); }catch(e){ return ''; }
  }
  function letterTile(host){
    const ch = (host.replace(/[^a-z0-9]/gi,'').charAt(0) || '?').toUpperCase();
    let h = 0; for(let k = 0; k < host.length; k++) h = (h * 31 + host.charCodeAt(k)) % 360;
    return '<span class="fav-letter" style="background:hsl(' + h + ',55%,72%)">' + ch + '</span>';
  }
  function faviconTag(url){
    let origin = '';
    try{ origin = new URL(url).origin; }catch(e){}
    const host = faviconHost(url);
    if(!origin || !host) return letterTile(host);
    const src = origin + '/favicon.ico';
    return '<img class="fav-icon" alt="" loading="lazy" referrerpolicy="no-referrer" src="' + src.replace(/"/g,'&quot;') +
           '" data-host="' + host.replace(/"/g,'&quot;') + '" data-step="0">';
  }
  function favFallback(img){
    const host = img.getAttribute('data-host') || '';
    const step = parseInt(img.getAttribute('data-step') || '0', 10);
    if(step === 0){
      img.setAttribute('data-step', '1');
      img.src = 'https://www.google.com/s2/favicons?sz=64&domain=' + encodeURIComponent(host);
    } else if(img.parentNode){
      const t = document.createElement('span');
      t.innerHTML = letterTile(host);
      img.replaceWith(t.firstChild);
    }
  }
  // Extension pages can't use inline onerror, so listen in the capture phase (error/load don't bubble).
  document.addEventListener('error', function(e){
    const t = e.target;
    if(t && t.tagName === 'IMG' && t.classList.contains('fav-icon')) favFallback(t);
  }, true);
  document.addEventListener('load', function(e){
    const t = e.target;
    if(t && t.tagName === 'IMG' && t.classList.contains('fav-icon') && t.naturalWidth < 8) favFallback(t); // 1x1 placeholder
  }, true);

  function iconTag(key, url){
    if((!key || key === 'link' || !ICONS[key]) && url) return faviconTag(url);
    const ic = ICONS[key] || ICONS.link;
    return '<i class="' + ic.fa + '" style="color:' + ic.color + '"></i>';
  }
