  // ---- Backgrounds (uploaded from device) ----
  const bgEl = document.getElementById('bgLayer');
  const bgGrid = document.getElementById('bgGrid');
  const bgFileInput = document.getElementById('bgFileInput');
  let bgs = load('horizon_bgs', []); // [{id, data}]
  if(!load('horizon_bgs_seeded', false)){
    bgs.push({ id: 'bg_preset_sniper', data: 'data:image/jpeg;base64,' });
    bgs.push({ id: 'bg_preset_g59', data: 'data:image/jpeg;base64,' });
    save('horizon_bgs', bgs);
    save('horizon_bgs_seeded', true);
  }
  let activeBg = load('horizon_active_bg', 'default');

  function applyActiveBg(){
    if(activeBg === 'default'){
      bgEl.style.backgroundImage = '';
    } else {
      const found = bgs.find(b => b.id === activeBg);
      if(found){
        bgEl.style.backgroundImage = "url('" + found.data + "')";
      } else activeBg = 'default';
    }
  }
  function renderBgGrid(){
    bgGrid.innerHTML = '';
    const defThumb = document.createElement('div');
    defThumb.className = 'bg-thumb' + (activeBg==='default' ? ' active' : '');
    defThumb.style.backgroundImage = "url('data:image/jpeg;base64,')";
    defThumb.title = 'Default';
    defThumb.addEventListener('click', ()=>{ activeBg='default'; save('horizon_active_bg', activeBg); applyActiveBg(); renderBgGrid(); });
    bgGrid.appendChild(defThumb);

    bgs.forEach(b=>{
      const thumb = document.createElement('div');
      thumb.className = 'bg-thumb' + (activeBg===b.id ? ' active' : '');
      thumb.style.backgroundImage = "url('" + b.data + "')";
      thumb.addEventListener('click', ()=>{ activeBg=b.id; save('horizon_active_bg', activeBg); applyActiveBg(); renderBgGrid(); });
      const del = document.createElement('div');
      del.className = 'del'; del.textContent = '×';
      del.addEventListener('click', (e)=>{
        e.stopPropagation();
        bgs = bgs.filter(x=>x.id!==b.id);
        save('horizon_bgs', bgs);
        if(activeBg===b.id){ activeBg='default'; save('horizon_active_bg', activeBg); applyActiveBg(); }
        renderBgGrid();
      });
      thumb.appendChild(del);
      bgGrid.appendChild(thumb);
    });
  }
  function compressImage(file){
    return new Promise((resolve, reject)=>{
      const img = new Image();
      const reader = new FileReader();
      reader.onload = ()=>{ img.src = reader.result; };
      reader.onerror = reject;
      img.onload = ()=>{
        const maxW = 1600;
        const scale = Math.min(1, maxW / img.width);
        const canvas = document.createElement('canvas');
        canvas.width = img.width * scale;
        canvas.height = img.height * scale;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        resolve(canvas.toDataURL('image/jpeg', 0.72));
      };
      img.onerror = reject;
      reader.readAsDataURL(file);
    });
  }
  async function addBackgroundFiles(fileList){
    const files = Array.from(fileList || []);
    for(const f of files){
      try{
        const data = await compressImage(f);
        const id = 'bg_' + Date.now() + '_' + Math.random().toString(36).slice(2,7);
        bgs.push({ id, data });
      }catch(e){ /* skip file on error */ }
    }
    save('horizon_bgs', bgs);
    renderBgGrid();
  }
