  // ---- Meteor cursor trail: a fading white streak follows the mouse for ~3s ----
  // Optimized to only run while needed: the render loop stops itself once the
  // trail has fully faded, and restarts on the next mouse move rather than
  // looping forever in the background.
  const meteorCanvas = document.getElementById('meteorCanvas');
  const meteorCtx = meteorCanvas.getContext('2d');
  let meteorPoints = [];
  let meteorLoopRunning = false;
  const METEOR_LIFETIME = 1800;
  const METEOR_MIN_DIST = 4;      // skip points that barely moved
  const METEOR_MAX_POINTS = 80;   // hard cap so a long idle drag can't grow unbounded

  function resizeMeteorCanvas(){
    meteorCanvas.width = window.innerWidth;
    meteorCanvas.height = window.innerHeight;
  }
  resizeMeteorCanvas();
  window.addEventListener('resize', resizeMeteorCanvas);

  function startMeteorLoop(){
    if(meteorLoopRunning) return;
    meteorLoopRunning = true;
    requestAnimationFrame(meteorLoop);
  }

  window.addEventListener('mousemove', (e)=>{
    if(!(settings.meteorTrail && !settings.reduceMotion)) return;
    const last = meteorPoints[meteorPoints.length - 1];
    if(last){
      const dx = e.clientX - last.x, dy = e.clientY - last.y;
      if((dx*dx + dy*dy) < METEOR_MIN_DIST * METEOR_MIN_DIST) return;
    }
    meteorPoints.push({ x:e.clientX, y:e.clientY, t: performance.now() });
    if(meteorPoints.length > METEOR_MAX_POINTS) meteorPoints.shift();
    startMeteorLoop();
  });

  function meteorLoop(){
    const now = performance.now();
    meteorPoints = meteorPoints.filter(p => now - p.t < METEOR_LIFETIME);
    meteorCtx.clearRect(0, 0, meteorCanvas.width, meteorCanvas.height);

    if(settings.meteorTrail && !settings.reduceMotion && meteorPoints.length > 1){
      meteorCtx.lineCap = 'round';
      for(let i=1; i<meteorPoints.length; i++){
        const p0 = meteorPoints[i-1], p1 = meteorPoints[i];
        const alpha = Math.max(0, 1 - (now - p1.t) / METEOR_LIFETIME);
        if(alpha <= 0.02) continue;
        meteorCtx.strokeStyle = `rgba(${meteorRGB[0]},${meteorRGB[1]},${meteorRGB[2]},${alpha})`;
        meteorCtx.lineWidth = 0.5 + 2 * alpha;
        // Shadow blur is the expensive part — only pay for it on the brighter,
        // recent segments where the glow is actually visible.
        meteorCtx.shadowBlur = alpha > 0.4 ? 8 * alpha : 0;
        meteorCtx.shadowColor = `rgba(${meteorRGB[0]},${meteorRGB[1]},${meteorRGB[2]},0.9)`;
        meteorCtx.beginPath();
        meteorCtx.moveTo(p0.x, p0.y);
        meteorCtx.lineTo(p1.x, p1.y);
        meteorCtx.stroke();
      }
      requestAnimationFrame(meteorLoop);
    } else {
      meteorLoopRunning = false; // nothing left to animate — loop stops until next mousemove
    }
  }

