    { name:'Forest', v:{ text:'#eaf5df', bar:'#b8f0a8', accent:'#8fd18a', highlight:'#d6d67a', linkCard:'#8fd18a', panelColor:'#0f2016', tintColor:'#08160c', tintStrength:25, meteorColor:'#b8f0a8' } },
    { name:'Violet', v:{ text:'#efe6ff', bar:'#c9b3ff', accent:'#b9a0ff', highlight:'#f0b9c8', linkCard:'#b9a0ff', panelColor:'#1a1230', tintColor:'#120a26', tintStrength:25, meteorColor:'#d4c2ff' } },
    { name:'Mono',   v:{ text:'#f2f2f2', bar:'#ffffff', accent:'#d0d0d0', highlight:'#ffffff', linkCard:'#ffffff', panelColor:'#141414', tintColor:'#000000', tintStrength:15, meteorColor:'#ffffff' } }
